#!/bin/bash
# Nd block zero-codepoints (hex), sampled across the Unicode range
blocks="0030 0660 06F0 07C0 0966 09E6 0A66 0AE6 0B66 0BE6 0C66 0CE6 0D66 0DE6 0E50 0ED0 0F20 1040 1090 17E0 1810 1946 19D0 1A80 1A90 1B50 1BB0 1C40 1C50 A620 A8D0 A900 A9D0 A9F0 AA50 ABF0 FF10 104A0 10D30 11066 110F0 11136 111D0 116C0 11C50 16A60 16B50 1D7CE 1D7D8 1D7E2 1D7EC 1D7F6 1E950 1FBF0"
for z in $blocks; do
  for v in 3 5; do
    cp=$(printf '%d' "0x$z"); cp=$((cp+v))
    esc=$(awk -f /tmp/probe/utf8.awk -v c=$cp 'BEGIN{print enc(c)}')
    echo "Nd U+$z +$v|2$esc:00"
  done
done
EOF
