function enc(cp) {
  if (cp < 0x80) return sprintf("\\x%02x", cp)
  else if (cp < 0x800) return sprintf("\\x%02x\\x%02x", 0xC0+int(cp/64), 0x80+(cp%64))
  else if (cp < 0x10000) return sprintf("\\x%02x\\x%02x\\x%02x", 0xE0+int(cp/4096), 0x80+(int(cp/64)%64), 0x80+(cp%64))
  else return sprintf("\\x%02x\\x%02x\\x%02x\\x%02x", 0xF0+int(cp/262144), 0x80+(int(cp/4096)%64), 0x80+(int(cp/64)%64), 0x80+(cp%64))
}
{ print $1 "|" enc($2+0) }
EOF
